 if fs::metadata(&manifest_path).map_err(|e|e.to_string())?.len()>16*1024*1024{return Err("Манифест проекта превышает 16 МиБ.".into());}
 let manifest:Value=serde_json::from_slice(&fs::read(&manifest_path).map_err(|e|e.to_string())?).map_err(|_|"Манифест не является корректным JSON")?;
 if manifest["format"]!="SMART_PHOTO_EDITOR"||(manifest["version"]!=1&&manifest["version"]!=2&&manifest["version"]!=3&&manifest["version"]!=4&&manifest["version"]!=5)||manifest["credentialsIncluded"]!=false{return Err("Неподдерживаемый или небезопасный формат проекта.".into());}
