  let hash=a["sha256"].as_str().unwrap();let existing:Option<String>=store::connection(app)?.query_row("SELECT id FROM editor_assets WHERE sha256=?1 AND kind=?2 LIMIT 1",params![hash,kind],|r|r.get(0)).optional().map_err(|e|e.to_string())?;let next_id=existing.unwrap_or_else(||format!("editor-{kind}-{hash}"));let next_relative=format!("{}/{hash}.{}",if kind=="mask"{"masks"}else{"assets"},extension(source).unwrap_or_else(||"png".into()));let next_preview=format!("previews/{hash}.png");for(input,relative)in[(source,&next_relative),(preview_source,&next_preview)]{let target=store::owned_path(app,relative)?;if !target.exists(){file_safety::atomic_save(&target,|out,_|{let mut input=fs::File::open(input).map_err(|e|e.to_string())?;std::io::copy(&mut input,out).map_err(|e|e.to_string())?;Ok(())})?;}if compute_file_sha256(&target)?!=compute_file_sha256(input)?{return Err("Owned-файл с таким адресом имеет другое содержимое; перезапись запрещена.".into());}}
  mapping.insert(old_id.to_string(),next_id.clone());ready.push(json!({"id":next_id,"kind":kind,"relativePath":next_relative,"previewPath":next_preview,"sha256":hash,"width":a["width"],"height":a["height"],"bytes":a["bytes"],"contentType":a["contentType"]}));
